package com.yosmitha.enterprise_iam.config;
import com.yosmitha.enterprise_iam.entity.*;import com.yosmitha.enterprise_iam.repository.*;import org.springframework.boot.CommandLineRunner;import org.springframework.context.annotation.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.security.crypto.password.PasswordEncoder;import java.util.*;
@Configuration public class SeedData{
 @Bean CommandLineRunner seed(RoleRepository roles,PermissionRepository perms,UserRepository users,PasswordEncoder enc,@Value("${app.bootstrap-admin.email}")String email,@Value("${app.bootstrap-admin.password}")String pass){return args->{Role user=roles.findByName("USER").orElseGet(()->roles.save(new Role("USER","Standard user")));Role admin=roles.findByName("ADMIN").orElseGet(()->roles.save(new Role("ADMIN","Administrator")));for(String p:List.of("USER_READ","USER_WRITE","ROLE_MANAGE","AUDIT_READ")){Permission x=perms.findByName(p).orElseGet(()->perms.save(new Permission(p,p)));admin.getPermissions().add(x);}if(!users.existsByEmail(email)){User u=new User();u.setFirstName("System");u.setLastName("Admin");u.setEmail(email);u.setPasswordHash(enc.encode(pass));u.setEmailVerified(true);u.getRoles().add(admin);users.save(u);}};}
}
